-- 选择性必修一 情景闯关题(context_questions, grade=10),由本地 vocab 真实例句挖空生成。Aaron 跑。
-- ContextQuiz 高中按 grade=10 + volume 读;写 volume/unit 防串库。幂等(只删本册)。
BEGIN;
DELETE FROM public.context_questions WHERE grade=10 AND volume='elective1';

COMMIT;
SELECT unit, count(*) FROM public.context_questions WHERE grade=10 AND volume='elective1' GROUP BY unit ORDER BY unit;
SELECT count(*) AS context_q_elective1 FROM public.context_questions WHERE grade=10 AND volume='elective1';
